"""Runs every sample build through the real checker and writes docs/SAMPLE_OUTPUTS.md."""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from core.catalog import Catalog
from core.checker import CompatibilityChecker
from core.models import CATEGORIES, CATEGORY_LABELS


def main():
    catalog = Catalog(ROOT / "data" / "components.json")
    checker = CompatibilityChecker()
    lines = ["# SystemX sample inputs and outputs", "",
             "Generated by `python tools/generate_sample_outputs.py` from the real checker.", "",
             "| # | Sample build | Expected | Actual | Match |", "|---|---|---|---|---|"]
    details = []
    for i, build in enumerate(catalog.sample_builds, 1):
        selection = catalog.selection_from_ids(build["selection"])
        report = checker.check(selection)
        actual = report.status.value
        lines.append(f"| {i} | {build['name']} | {build['expected']} | {actual} | {'yes' if actual == build['expected'] else 'NO'} |")
        details += [f"## {i}. {build['name']}", "", build.get("description", ""), "", "**Input**", ""]
        for cat in CATEGORIES:
            part = selection.get(cat)
            details.append(f"- {CATEGORY_LABELS[cat]}: {part.name if part else '(not selected)'}")
        details += ["", f"**Output: {actual}** - {report.headline}", "",
                    f"`Compatible = {report.expression}`  ", f"`           = {report.substituted}`", ""]
        for r in report.results:
            details.append(f"- {r.symbol} [{r.state}] {r.statement}: {r.reason}")
        details.append("")
    out = ROOT / "docs" / "SAMPLE_OUTPUTS.md"
    out.write_text("\n".join(lines + [""] + details), encoding="utf-8")
    print("wrote", out)


if __name__ == "__main__":
    main()
